"""Value formatting that mimics Rust's Display for f64 and fselect's output style."""

import datetime
from decimal import Decimal


def format_float(v: float) -> str:
    if v != v:  # NaN
        return "NaN"
    if v == float("inf"):
        return "inf"
    if v == float("-inf"):
        return "-inf"
    if v == int(v) and abs(v) < 1e15:
        return str(int(v))
    s = repr(v)
    if "e" in s or "E" in s:
        # Rust Display never uses scientific notation
        s = format(Decimal(s), "f")
    return s


def format_value(v) -> str:
    """Convert an evaluated expression value to its display string."""
    if v is None:
        return ""
    if isinstance(v, bool):
        return "true" if v else "false"
    if isinstance(v, int):
        return str(v)
    if isinstance(v, float):
        return format_float(v)
    if isinstance(v, datetime.datetime):
        return v.strftime("%Y-%m-%d %H:%M:%S")
    if isinstance(v, datetime.date):
        return v.strftime("%Y-%m-%d")
    return str(v)

"""Date/time parsing mimicking the chrono-english dialect used by fselect.

parse_datetime(text, us_dates) -> (datetime, precision) or raises ValueError.
precision is one of 'day', 'hour', 'minute', 'second'.
"""

import datetime
import re

MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

WEEKDAYS = {
    "mon": 0, "monday": 0,
    "tue": 1, "tues": 1, "tuesday": 1,
    "wed": 2, "wednesday": 2,
    "thu": 3, "thur": 3, "thurs": 3, "thursday": 3,
    "fri": 4, "friday": 4,
    "sat": 5, "saturday": 5,
    "sun": 6, "sunday": 6,
}

ISO_RE = re.compile(
    r"^(\d{4})-(\d{1,2})-(\d{1,2})(?:[ T](\d{1,2})(?::(\d{1,2})(?::(\d{1,2})(?:\.\d+)?)?)?)?$"
)
TIME_RE = re.compile(r"^(\d{1,2}):(\d{1,2})(?::(\d{1,2})(?:\.\d+)?)?$")
SLASH_RE = re.compile(r"^(\d{1,2})/(\d{1,2})(?:/(\d{2,4}))?$")
AGO_RE = re.compile(
    r"^(\d+)\s+(second|seconds|sec|secs|minute|minutes|min|mins|hour|hours|day|days|week|weeks|month|months|year|years)\s+ago$"
)
LASTNEXT_RE = re.compile(r"^(last|next)\s+([a-z]+)$")


class DateParseError(ValueError):
    pass


def _days_in_month(y, m):
    if m == 12:
        return 31
    return (datetime.date(y, m + 1, 1) - datetime.date(y, m, 1)).days


def _shift_months(dt, months):
    total = dt.year * 12 + (dt.month - 1) + months
    y, m0 = divmod(total, 12)
    m = m0 + 1
    d = min(dt.day, _days_in_month(y, m))
    return dt.replace(year=y, month=m, day=d)


def _apply_time(dt, hour, minute, second):
    if hour is None:
        return dt, "day"
    if minute is None:
        return dt.replace(hour=int(hour), minute=0, second=0), "hour"
    if second is None:
        return dt.replace(hour=int(hour), minute=int(minute), second=0), "minute"
    return dt.replace(hour=int(hour), minute=int(minute), second=int(second)), "second"


def parse_datetime(text, us_dates=False, now=None):
    """Parse a datetime string. Returns (datetime, precision)."""
    if now is None:
        now = datetime.datetime.now()
    s = text.strip()
    low = s.lower()

    m = ISO_RE.match(s)
    if m:
        y, mo, d, hh, mm, ss = m.groups()
        try:
            dt = datetime.datetime(int(y), int(mo), int(d))
        except ValueError:
            raise DateParseError(text)
        try:
            return _apply_time(dt, hh, mm, ss)
        except ValueError:
            raise DateParseError(text)

    m = TIME_RE.match(s)
    if m:
        hh, mm, ss = m.groups()
        try:
            dt = now.replace(hour=int(hh), minute=int(mm), second=int(ss or 0), microsecond=0)
        except ValueError:
            raise DateParseError(text)
        prec = "minute" if ss is None else "second"
        return dt, prec

    m = SLASH_RE.match(s)
    if m:
        a, b, y = m.groups()
        a, b = int(a), int(b)
        if us_dates:
            mo, d = a, b
        else:
            d, mo = a, b
        y = int(y) if y else now.year
        if y < 100:
            y += 2000
        try:
            return datetime.datetime(y, mo, d), "day"
        except ValueError:
            raise DateParseError(text)

    if low in ("today",):
        return now.replace(hour=0, minute=0, second=0, microsecond=0), "day"
    if low in ("yesterday",):
        return (now - datetime.timedelta(days=1)).replace(hour=0, minute=0, second=0, microsecond=0), "day"
    if low in ("tomorrow",):
        return (now + datetime.timedelta(days=1)).replace(hour=0, minute=0, second=0, microsecond=0), "day"

    m = AGO_RE.match(low)
    if m:
        n = int(m.group(1))
        unit = m.group(2)
        now0 = now.replace(microsecond=0)
        if unit.startswith("sec"):
            return now0 - datetime.timedelta(seconds=n), "second"
        if unit.startswith("min"):
            return now0 - datetime.timedelta(minutes=n), "second"
        if unit.startswith("hour"):
            return now0 - datetime.timedelta(hours=n), "second"
        if unit.startswith("day"):
            return now0 - datetime.timedelta(days=n), "second"
        if unit.startswith("week"):
            return now0 - datetime.timedelta(weeks=n), "second"
        if unit.startswith("month"):
            return _shift_months(now0, -n), "second"
        if unit.startswith("year"):
            return _shift_months(now0, -12 * n), "second"

    m = LASTNEXT_RE.match(low)
    if m:
        which, what = m.groups()
        if what in WEEKDAYS:
            target = WEEKDAYS[what]
            today = now.replace(hour=0, minute=0, second=0, microsecond=0)
            cur = today.weekday()
            if which == "last":
                delta = (cur - target) % 7
                if delta == 0:
                    delta = 7
                return today - datetime.timedelta(days=delta), "day"
            else:
                delta = (target - cur) % 7
                if delta == 0:
                    delta = 7
                return today + datetime.timedelta(days=delta), "day"
        if what == "month":
            now0 = now.replace(microsecond=0)
            return _shift_months(now0, -1 if which == "last" else 1), "second"
        # "last week", "last year", "next year" etc. are rejected
        raise DateParseError(text)

    # "15 may [2020]" or "may 15" (optionally with time)
    tokens = low.split()
    if tokens:
        base_tokens = tokens
        hh = mm = ss = None
        if len(tokens) >= 2:
            tm = TIME_RE.match(tokens[-1])
            if tm:
                hh, mm, ss = tm.groups()
                base_tokens = tokens[:-1]
        dt = None
        if len(base_tokens) == 2:
            t0, t1 = base_tokens
            if t0.isdigit() and t1 in MONTHS:
                dt = _safe_date(now.year, MONTHS[t1], int(t0))
            elif t1.isdigit() and t0 in MONTHS:
                dt = _safe_date(now.year, MONTHS[t0], int(t1))
        elif len(base_tokens) == 3:
            t0, t1, t2 = base_tokens
            # only "15 may 2020" form is accepted (day month year)
            if t0.isdigit() and t1 in MONTHS and t2.isdigit():
                dt = _safe_date(int(t2), MONTHS[t1], int(t0))
        if dt is not None:
            try:
                return _apply_time(dt, hh, mm, ss)
            except ValueError:
                raise DateParseError(text)

    raise DateParseError(text)


def _safe_date(y, m, d):
    try:
        return datetime.datetime(y, m, d)
    except ValueError:
        raise DateParseError("%04d-%02d-%02d" % (y, m, d))


def interval_for(dt, precision):
    """Return (start, end) datetimes covering the stated precision."""
    if precision == "day":
        start = dt.replace(hour=0, minute=0, second=0, microsecond=0)
        end = dt.replace(hour=23, minute=59, second=59, microsecond=999999)
    elif precision == "hour":
        start = dt.replace(minute=0, second=0, microsecond=0)
        end = dt.replace(minute=59, second=59, microsecond=999999)
    elif precision == "minute":
        start = dt.replace(second=0, microsecond=0)
        end = dt.replace(second=59, microsecond=999999)
    else:
        start = end = dt
    return start, end
